ALTER TABLE "grants" DROP CONSTRAINT "grants_actions_check";--> statement-breakpoint
ALTER TABLE "grants" DROP CONSTRAINT "grants_actions_resource_check";--> statement-breakpoint
ALTER TABLE "slack_inbound_events" DROP CONSTRAINT "slack_inbound_events_drop_reason_check";--> statement-breakpoint
ALTER TABLE "surface_bindings" DROP CONSTRAINT "surface_bindings_status_check";--> statement-breakpoint
ALTER TABLE "surface_bindings" ADD COLUMN "approved_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "grants" ADD CONSTRAINT "grants_actions_check" CHECK (cardinality("grants"."actions") > 0 AND coalesce(array_ndims("grants"."actions"), 1) = 1 AND "grants"."actions" <@ ARRAY['workspace.read','workspace.manage','agent.manage','binding.manage','binding.approve','routine.manage','session.read','session.submit','session.approve','session.control','session.recover','memory.read','memory.write','artifact.read','delivery.send']::text[]);--> statement-breakpoint
ALTER TABLE "grants" ADD CONSTRAINT "grants_actions_resource_check" CHECK ("grants"."actions" <@ CASE "resource_kind" WHEN 'workspace' THEN ARRAY['workspace.read','workspace.manage','agent.manage','binding.manage','binding.approve','routine.manage','memory.read','memory.write']::text[] WHEN 'session' THEN ARRAY['session.read','session.submit','session.approve','session.control','session.recover','artifact.read','delivery.send']::text[] WHEN 'invite' THEN ARRAY[]::text[] WHEN 'agent' THEN ARRAY['agent.manage','binding.manage','binding.approve','routine.manage','memory.read','memory.write']::text[] WHEN 'agent_release' THEN ARRAY[]::text[] WHEN 'surface_binding' THEN ARRAY['binding.manage','binding.approve','session.submit','delivery.send']::text[] WHEN 'session_link' THEN ARRAY['session.read','session.submit','session.approve','session.control','delivery.send']::text[] WHEN 'dispatch' THEN ARRAY[]::text[] WHEN 'memory' THEN ARRAY['memory.read','memory.write']::text[] WHEN 'routine' THEN ARRAY['routine.manage']::text[] WHEN 'artifact' THEN ARRAY['artifact.read']::text[] ELSE ARRAY[]::text[] END);--> statement-breakpoint
ALTER TABLE "slack_inbound_events" ADD CONSTRAINT "slack_inbound_events_drop_reason_check" CHECK ("slack_inbound_events"."drop_reason" IS NULL OR "slack_inbound_events"."drop_reason" IN ('not_installed','installation_unverified','installation_revoked','unidentified','identity_revoked','bot_mismatch','agent_mismatch','agent_archived','app_mismatch','bot_message','own_bot_user','message_subtype','unsupported_event','user_tokens_only','channel_pending_approval')) NOT VALID;--> statement-breakpoint
ALTER TABLE "surface_bindings" ADD CONSTRAINT "surface_bindings_status_check" CHECK ("surface_bindings"."status" IN ('ready','pending_approval','partial','failed','revoked'));--> statement-breakpoint
UPDATE "surface_bindings" SET "status" = 'pending_approval', "home" = false, "revision" = "revision" + 1, "updated_at" = now() WHERE "surface" = 'slack' AND "surface_kind" = 'private_channel' AND "status" = 'ready' AND "revoked_at" IS NULL AND "installation_id" IS NOT NULL AND "external_surface_id" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "surface_bindings" ADD CONSTRAINT "surface_bindings_pending_check" CHECK ("surface_bindings"."status" <> 'pending_approval' OR ("surface_bindings"."surface" = 'slack' AND "surface_bindings"."installation_id" IS NOT NULL AND "surface_bindings"."external_surface_id" IS NOT NULL AND "surface_bindings"."surface_kind" = 'private_channel' AND NOT "surface_bindings"."home"));
